Get-Counter -Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $readings = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($readings | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($readings | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPercent = [math]::Round(($readings | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize

Get-Counter -Counter '\Processor(_Total)\% Processor Time','\System\Processor Queue Length','\Memory\Available MBytes','\Memory\Committed Bytes','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes' -SampleInterval 5 -MaxSamples 3 |
  ForEach-Object {
    $_.Timestamp
    $_.CounterSamples | Format-Table Path,CookedValue -AutoSize
  }

Get-Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $readings = $_.CounterSamples
    [pscustomobject]@{
        Time = $_.Timestamp
        FreeGiB = [math]::Round((($readings | Where-Object Path -Like '*\available mbytes').CookedValue / 1024), 2)
        CommitGiB = [math]::Round((($readings | Where-Object Path -Like '*\committed bytes').CookedValue / 1GB), 2)
        CPUPercent = [math]::Round(($readings | Where-Object Path -Like '*\% processor time').CookedValue, 1)
    }
} | Format-Table -AutoSize

$samples = @(Get-Counter -Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop | ForEach-Object {
    $r = $_.CounterSamples
    [pscustomobject]@{
        FreeMiB = ($r | Where-Object Path -Like '*\available mbytes').CookedValue
        CommitBytes = ($r | Where-Object Path -Like '*\committed bytes').CookedValue
        CPU = ($r | Where-Object Path -Like '*\% processor time').CookedValue
    }
})
$first = $samples[0]
$last = $samples[-1]
$commitChange = ($last.CommitBytes - $first.CommitBytes) / 1GB
$freeChange = ($last.FreeMiB - $first.FreeMiB) / 1024
$minCPU = ($samples | Measure-Object CPU -Minimum).Minimum
$maxCPU = ($samples | Measure-Object CPU -Maximum).Maximum
$ram = if ($commitChange -ge 0.5 -and $freeChange -le -0.5) {
    'Commit rose and free RAM fell: memory pressure is worsening. Recheck after builds go idle.'
} elseif ($commitChange -le -0.5 -and $freeChange -ge 0.5) {
    'Commit fell and free RAM rose: memory pressure is recovering.'
} else {
    'No clear system-wide memory trend in this sample.'
}
$cpu = if ($minCPU -ge 85) {
    'CPU stayed at or above 85%: check for a busy process if builds are idle.'
} else {
    'CPU did not stay at or above 85% during this sample.'
}
'RAM: {0} (commit {1:+0.00;-0.00;0.00} GiB, free {2:+0.00;-0.00;0.00} GiB)' -f $ram, $commitChange, $freeChange
'CPU: {0} (range {1:0.0}-{2:0.0}%)' -f $cpu, $minCPU, $maxCPU

Get-Counter -Counter @('\Memory\Available MBytes','\Memory\Committed Bytes','\Processor(_Total)\% Processor Time') -SampleInterval 5 -MaxSamples 6 -ErrorAction Stop |
    ForEach-Object {
        $sample = $_
        $sample.CounterSamples | Select-Object @{Name='Time';Expression={$sample.Timestamp}}, Path, CookedValue
    } | Format-Table -AutoSize

Get-Counter -Counter '\Processor(_Total)\% Processor Time','\System\Processor Queue Length','\Memory\Available MBytes','\Memory\Committed Bytes','\Memory\Pool Nonpaged Bytes','\Memory\Pool Paged Bytes' -SampleInterval 5 -MaxSamples 3 |
  ForEach-Object { $_.Timestamp; $_.CounterSamples | Format-Table Path,CookedValue -AutoSize }
$poolSnapshot = Join-Path $env:TEMP ("pool-{0:yyyyMMdd-HHmmss}.txt" -f (Get-Date))
poolmon.exe /b /n $poolSnapshot
if (Test-Path -LiteralPath $poolSnapshot) { Get-Content -LiteralPath $poolSnapshot -TotalCount 20 }

